function calParse(line){
  var t=String(line||'').trim(); if(!t) return { error:'空行' };
  var toks=t.split(/\s+/);
  var ki=-1;
  for(var i=0;i<toks.length;i++){ if(/^\d+(\.\d+)?$/.test(toks[i])){ ki=i; break; } }
  if(ki<0) return { error:'缺少热量(kcal)：'+t };
  var kcal=parseFloat(toks[ki]);
  var name=toks.slice(0,ki).join(' ');
  var protein=0,carbs=0,fat=0;
  for(var j=ki+1;j<toks.length;j++){
    var mp=toks[j].match(/^p(\d+(?:\.\d+)?)$/i); if(mp){ protein=+mp[1]; continue; }
    var mc=toks[j].match(/^c(\d+(?:\.\d+)?)$/i); if(mc){ carbs=+mc[1]; continue; }
    var mf=toks[j].match(/^f(\d+(?:\.\d+)?)$/i); if(mf){ fat=+mf[1]; continue; }
  }
  return { error:null, name:name||'食物', kcal:kcal, protein:protein, carbs:carbs, fat:fat };
}
function calSummary(entries){
  var t={kcal:0,protein:0,carbs:0,fat:0};
  for(var i=0;i<entries.length;i++){ t.kcal+=entries[i].kcal; t.protein+=entries[i].protein; t.carbs+=entries[i].carbs; t.fat+=entries[i].fat; }
  return t;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { calParse:calParse, calSummary:calSummary };
}
if (typeof window !== 'undefined') {
  window.CalorieForgePure = { calParse:calParse, calSummary:calSummary };
}
